# Fallback for postflop keys with too few samples: mean over board categories.
_POST_FB = {}
for (_st, _my, _bc, _k), _v in POST.items():
    _POST_FB.setdefault((_st, _my, _k), []).append(_v)
_POST_FB = {key: sum(v) / len(v) for key, v in _POST_FB.items()}


def hand_class(c1, c2):
    a, b = c1[0], c2[0]
    if _RV[a] < _RV[b]:
        a, b = b, a
    if a == b:
        return a + b + "p"
    return a + b + ("s" if c1[1] == c2[1] else "o")


def board_category(board):
    """Category the visible board alone makes (rank counts if under 5 cards)."""
    if len(board) >= 5:
        return evaluate(board, validate=False)[0]
    counts = {}
    for c in board:
        counts[c[0]] = counts.get(c[0], 0) + 1
    shape = sorted(counts.values(), reverse=True)
    if shape[0] == 4:
        return FOUR_OF_A_KIND
    if shape[0] == 3:
        return FULL_HOUSE if len(shape) > 1 and shape[1] >= 2 else THREE_OF_A_KIND
    if shape[0] == 2:
        return TWO_PAIR if len(shape) > 1 and shape[1] == 2 else PAIR
    return HIGH_CARD


def _post_lookup(street, my, bc, k):
    v = POST.get((street, my, bc, k))
    if v is None:
        v = _POST_FB.get((street, my, k))
    if v is None:
        v = 1.0 / (k + 1)
    return v


def _interp(f, k):
    """f(int k) interpolated at real k, clamped to 1..7."""
    k = min(7.0, max(1.0, k))
    lo = int(k)
    if lo >= 7 or k == lo:
        return f(lo)
    t = k - lo
    return (1 - t) * f(lo) + t * f(lo + 1)


class Bot(Agent):
    def __init__(self) -> None:
        self.rng = random.Random(20261101)  # fixed: reproducible A/B runs on the same --seed
        self.faced = [0] * SEATS     # open raises faced (preflop, this table)
        self.folds = [0] * SEATS     # ... and folded to
        self._cache_key = None
        self._cache = None

    # ------------------------------------------------------------ interface
    def decide(self, obs: Observation) -> Action:
        if DEBUG:
            self._check_invariants(obs)
            act = self._decide(obs)
            if act.kind == RAISE:
                assert RAISE in obs.legal_actions, "raise not legal"
                assert obs.min_raise_to <= act.amount <= obs.max_raise_to, \
                    f"raise {act.amount} outside [{obs.min_raise_to}, {obs.max_raise_to}]"
            return act
        try:
            return self._decide(obs)
        except Exception:
            try:
                return Action.check() if CHECK in obs.legal_actions else Action.fold()
            except Exception:
                return Action.fold()

    def hand_over(self, summary: HandSummary) -> None:
        try:
            opened = False
            seen = set()
            for e in summary.history:
                if e.street != PREFLOP:
                    break
                if e.kind in (ANTE, SMALL_BLIND, BIG_BLIND):
                    continue
                if e.kind == RAISE:
                    if opened:
                        break
                    opened = True
                    seen.add(e.seat)
                    continue
                if opened and e.seat not in seen:
                    seen.add(e.seat)
                    self.faced[e.seat] += 1
                    if e.kind == FOLD:
                        self.folds[e.seat] += 1
        except Exception:
            pass

    # ------------------------------------------------------------ helpers
    def fold_rate(self, seat):
        return (self.folds[seat] + 1) / (self.faced[seat] + 2)

    def _categories(self, obs):
        key = (obs.hand_number, obs.street)
        if self._cache_key != key:
            my = evaluate(list(obs.hole) + list(obs.board), validate=False)[0]
            self._cache = (my, board_category(obs.board))
            self._cache_key = key
        return self._cache

    @staticmethod
    def _raise_to(obs, amount):
        if RAISE not in obs.legal_actions:
            return Action.call() if CALL in obs.legal_actions else Action.check()
        return Action.raise_(int(max(obs.min_raise_to, min(obs.max_raise_to, amount))))

    @staticmethod
    def _premium(call, stack, left, fraction, strict):
        big = call >= stack or (call > fraction * stack if strict else call >= fraction * stack)
        return ICM_BASE * (1 + ICM_PER_PLAYER * (SEATS - left)) if big else 0.0

    # ------------------------------------------------------------ strategy
    def _decide(self, obs):
        legal = obs.legal_actions
        players = obs.players
        me = players[obs.seat]
        bb = obs.big_blind
        passive = Action.check() if CHECK in legal else Action.fold()
        pot_now = obs.pot + sum(p.committed for p in players)
        opps = [p for p in players if p.seat != obs.seat and p.status in _LIVE]
        if not opps:
            return passive
        my_total = me.stack + me.committed
        eff = min(my_total, max(p.stack + p.committed for p in opps)) / bb
        left = sum(1 for p in players if p.status != OUT)
        call = min(obs.to_call, me.stack)
        if obs.street == PREFLOP:
            return self._preflop(obs, legal, players, me, bb, passive, pot_now, eff, left, call)
        return self._postflop(obs, legal, me, passive, pot_now, opps, left, call)

    def _preflop(self, obs, legal, players, me, bb, passive, pot_now, eff, left, call):
        hist = [e for e in obs.history if e.street == PREFLOP]
        raises = [e for e in hist if e.kind == RAISE]
        cls = hand_class(*obs.hole)
        if not raises:
            limpers = len({e.seat for e in hist if e.kind == CALL and e.seat != obs.seat
                           and players[e.seat].status in _LIVE})
            # seats still to act: after me in preflop order, up to the big blind
            behind = []
            if obs.seat != obs.big_blind_seat:
                s = obs.seat
                while True:
                    s = (s + 1) % SEATS
                    if players[s].status in _LIVE and s != obs.seat:
                        behind.append(s)
                    if s == obs.big_blind_seat or s == obs.seat:
                        break
            behind = [s for s in behind if not any(e.seat == s and e.kind == CALL for e in hist)]
            k = max(1, min(7, len(behind) + limpers))
            factor = 1.0
            if behind and len(behind) <= STEAL_MAX_BEHIND and limpers == 0:
                rate = sum(self.fold_rate(s) for s in behind) / len(behind)
                factor = 1 - STEAL_WEIGHT * max(0.0, 2 * rate - 1)
            eq = PRE.get((cls, k), 1.0 / (k + 1))
            if eff <= PUSH_DEPTH_BB:
                bar = (PUSH_BASE + PUSH_SLOPE * eff / PUSH_DEPTH_BB) / (k + 1) * factor
                if eq >= bar:
                    return self._raise_to(obs, obs.max_raise_to)
                return passive
            if eq >= OPEN_BAR / (k + 1) * factor:
                return self._raise_to(obs, (2 + limpers) * bb)
            return passive

        if obs.to_call <= 0:
            return passive
        last = raises[-1]
        extra = len({e.seat for e in hist if e.kind in (CALL, RAISE) and e.seat != last.seat
                     and e.seat != obs.seat and players[e.seat].status in _LIVE})
        k = RAISER_HANDS + EXTRA_PLAYER_HANDS * extra
        eq = _interp(lambda n: PRE.get((cls, n), 1.0 / (n + 1)), k)
        if eq >= RERAISE_EQ and RAISE in legal:
            if eff <= RERAISE_SHOVE_BB:
                return self._raise_to(obs, obs.max_raise_to)
            return self._raise_to(obs, RERAISE_MULT * last.amount)
        need = call / (pot_now + call) + CALL_MARGIN
        need += self._premium(call, me.stack, left, ICM_FRACTION_PRE, strict=True)
        if eq >= need:
            return Action.call()
        return passive

    def _postflop(self, obs, legal, me, passive, pot_now, opps, left, call):
        k = max(1, min(7, len(opps)))
        my, bc = self._categories(obs)
        eq = _post_lookup(obs.street, my, bc, k)
        if obs.to_call > 0:
            n_raises = sum(1 for e in obs.history if e.street == obs.street and e.kind == RAISE)
            adj = eq * POST_RAISE_DISCOUNT ** n_raises
            need = call / (pot_now + call) + CALL_MARGIN
            need += self._premium(call, me.stack, left, ICM_FRACTION_POST, strict=False)
            if adj >= max(POST_RAISE_EQ, need + POST_RAISE_MARGIN) and RAISE in legal:
                current = me.committed + obs.to_call
                return self._raise_to(obs, current + pot_now + obs.to_call)
            if adj >= need:
                return Action.call()
            return passive
        if RAISE in legal:
            if eq >= BET_EQ:
                return self._raise_to(obs, BET_FRACTION * pot_now)
            if obs.street == "flop" and k == 1 and self._was_preflop_raiser(obs) \
                    and self.rng.random() < CBET_FREQ:
                return self._raise_to(obs, CBET_FRACTION * pot_now)
        return passive

    @staticmethod
    def _was_preflop_raiser(obs):
        last = None
        for e in obs.history:
            if e.street == PREFLOP and e.kind == RAISE:
                last = e.seat
        return last == obs.seat

    # ------------------------------------------------------------ debug
    def _check_invariants(self, obs):
        put_in = 0
        street_put = {}
        for e in obs.history:
            if e.kind in (ANTE,):
                put_in += e.amount
                continue
            key = (e.street, e.seat)
            if e.kind in (SMALL_BLIND, BIG_BLIND, CALL):
                street_put[key] = street_put.get(key, 0) + e.amount
                put_in += e.amount
            elif e.kind == RAISE:
                prev = street_put.get(key, 0)
                put_in += e.amount - prev
                street_put[key] = e.amount
        pot_now = obs.pot + sum(p.committed for p in obs.players)
        assert pot_now == put_in, f"pot {pot_now} != chips put in {put_in}"
        total = pot_now + sum(p.stack for p in obs.players)
        assert total == STARTING_TOTAL, f"chips {total} != {STARTING_TOTAL}"
        assert obs.players[obs.seat].committed == street_put.get((obs.street, obs.seat), 0)
